import XCTest
@testable import PiyaliCore
final class ScholarshipPromptTests:XCTestCase {
    func testQueuedPromptWaitsForOtherModalAndDismissesOnlyForItsAccount(){var flow=ScholarshipPrompt();flow.request(account:"one",target:"es",seen:false);flow.present(account:"one",target:"es",seen:false,blocked:true);XCTAssertNil(flow.visible);XCTAssertNotNil(flow.pending);flow.present(account:"one",target:"es",seen:false,blocked:false);XCTAssertNotNil(flow.visible);XCTAssertFalse(flow.dismiss(account:"two",target:"es"));XCTAssertTrue(flow.dismiss(account:"one",target:"es"));XCTAssertNil(flow.visible);XCTAssertNil(flow.pending)}
    func testSeenAccountAndContextChangesDiscardLateRequests(){var flow=ScholarshipPrompt();flow.request(account:"one",target:"es",seen:true);XCTAssertNil(flow.pending);flow.request(account:"one",target:"es",seen:false);flow.present(account:"two",target:"es",seen:false,blocked:false);XCTAssertNil(flow.visible);XCTAssertNil(flow.pending);flow.request(account:"two",target:"es",seen:false);flow.reconcile(account:"two",target:"fr",seen:false);XCTAssertNil(flow.pending);flow.request(account:"two",target:"fr",seen:false);flow.present(account:"two",target:"fr",seen:false,blocked:false);flow.reconcile(account:"two",target:"fr",seen:true);XCTAssertNil(flow.visible)}
    func testSourceRetargetKeepsOnlySubmittedIntentAndNeverAddsFees()throws{var journal=AutomaticTipJournal();journal.configure(enabled:true,recipient:"first",maximumFee:0,sourceManaged:true);let a=PracticeChange(dayKey:"day",target:"es",level:"A1",amount:5,source:.practice),b=PracticeChange(dayKey:"day",target:"es",level:"A1",amount:10,source:.practice);journal.enqueue([a,b],available:10);journal.retargetSourceSupport("next",activeID:a.id.uuidString.lowercased());XCTAssertEqual(journal.queue.count,1);XCTAssertEqual(journal.queue[0].recipient,"first");XCTAssertEqual(journal.maximumFee,0);let c=PracticeChange(dayKey:"day",target:"es",level:"A1",amount:5,source:.practice);journal.enqueue([a,b,c],available:10);XCTAssertEqual(journal.queue.map(\.recipient),["first","next"]);let restored=try JSONDecoder().decode(AutomaticTipJournal.self,from:JSONEncoder().encode(journal));XCTAssertEqual(restored.sourceManaged,true)}
}
